const q = $input.first().json.query || {};
const expected = "F1h0b14n4";
const ok = q["hub.mode"] === "subscribe" && q["hub.verify_token"] === expected;
return [{
  json: {
    ok,
    responseBody: ok ? String(q["hub.challenge"] || "") : "Forbidden",
  }
}];

// ============================================================================
// 1. Extraire sender + texte (ou image) du payload webhook Meta. Ignore silencieusement tout ce qui
//    n'est ni l'un ni l'autre (statuts de livraison, etc.).
// ============================================================================
const body = $input.first().json.body || {};
let sender = null, text = null, imageId = null, imageCaption = "";
for (const entry of (body.entry || [])) {
  for (const change of (entry.changes || [])) {
    for (const msg of ((change.value || {}).messages || [])) {
      if (msg.type === "text") { sender = msg.from; text = msg.text.body; }
      else if (msg.type === "image" && msg.image && msg.image.id) {
        sender = msg.from; imageId = msg.image.id; imageCaption = msg.image.caption || "";
      }
    }
  }
}
if (!sender) return [];

// ============================================================================
// 2. Whitelist équipe Nuklear. Laisser vide = tout le monde autorisé.
// ============================================================================
// Vide par défaut = tout le monde autorisé (comme whatsapp.py::allowed_senders() côté Python).
// Remplir avec des numéros séparés par des virgules pour activer la whitelist équipe Nuklear.
const ALLOWED_SENDERS = ""; // ex: "+261340000000,+261320000000"
const allowedList = ALLOWED_SENDERS.split(",").map(s => s.trim()).filter(Boolean);
if (allowedList.length && !allowedList.includes(sender)) {
  return [{ json: { sender, needsBrain: false, text: "⛔ Accès réservé à l'équipe Nuklear.", image_url: null } }];
}

// ============================================================================
// 3. État de conversation persistant (mémoire n8n native -- survit entre
//    exécutions, pas de base de données requise).
// ============================================================================
const staticData = $getWorkflowStaticData('global');
staticData.sessions = staticData.sessions || {};
const state = staticData.sessions[sender] || { stage: "idle", platform: null, current_idea: null, refine_notes: [], chat_history: [] };

// ============================================================================
// Limite quotidienne par expéditeur -- partagée par TOUTES les voies (commande texte, conversation
// "chat", feedback sur image). Protège les forfaits gratuits partagés par toute l'équipe (Tavily
// 1000 req/mois, Cloudinary 25 crédits/mois) ET le budget Anthropic (facturé au token) : sans plafond
// commun, un usage un peu intensif -- ou une conversation "chat"/des feedbacks image laissés ouverts --
// épuise le quota/budget du mois en quelques jours sans que personne ne s'en rende compte à l'avance.
// Factorisée en fonction (au lieu d'un bloc dupliqué par voie) pour ne jamais désynchroniser le compteur.
// ============================================================================
const DAILY_LIMIT_PER_SENDER = 15; // ~450/mois si utilisé tous les jours -- ajuster si besoin
function quotaExceeded(senderId) {
  const today = new Date().toISOString().slice(0, 10);
  staticData.usage = staticData.usage || {};
  const usageKey = `${senderId}:${today}`;
  staticData.usage[usageKey] = staticData.usage[usageKey] || 0;
  if (staticData.usage[usageKey] >= DAILY_LIMIT_PER_SENDER) return true;
  staticData.usage[usageKey] += 1;
  return false;
}
const QUOTA_MESSAGE = `⏳ Limite quotidienne atteinte (${DAILY_LIMIT_PER_SENDER} générations/jour) pour préserver les forfaits gratuits partagés par l'équipe. Réessaie demain.`;

// ============================================================================
// 3bis. Image envoyée par l'équipe = demande de FEEDBACK CRÉATIF (nouvelle fonctionnalité) : Nuklear
// analyse le visuel (création propre, brief client, capture d'écran d'un concurrent...) et rend un
// avis d'expert digital -- design, lisibilité, message, hiérarchie visuelle. Court-circuite tout le
// parsing de commande texte ci-dessous : une image n'a pas de "commande", juste une légende WhatsApp
// optionnelle qui précise la question ("cette pub, elle marche ?").
// ============================================================================
if (imageId) {
  if (quotaExceeded(sender)) return [{ json: { sender, needsBrain: false, text: QUOTA_MESSAGE, image_url: null } }];
  return [{ json: {
    sender, needsBrain: true, command: "vision",
    platform: state.platform || "instagram",
    freeText: imageCaption, imageId, state,
  } }];
}

// ============================================================================
// 4. Parsing de commande.
// ============================================================================
const HELP_TEXT = [
  "🤖 *Nuklear Content Agent* — commandes disponibles:",
  "",
  "1️⃣ *gen image insta* / *gen image facebook*",
  "   → Idée de visuel basée sur les tendances + concurrents en temps réel. Idée libre : `gen image insta: astuce SEO local`",
  "",
  "2️⃣ *gen video*",
  "   → Prompt vidéo précis (avant/après, astuce, mythe vs réalité...).",
  "",
  "🎯 *gen collection: <idée>* / *gen avant apres: <idée>* / *gen annonce: <idée>*",
  "   → Force directement ce format (grille de photos / split-screen / paysage texte), sans dépendre de la détection automatique.",
  "",
  "3️⃣ *gen recrutement: <poste> | <contrat> | <lieu> | <email>*",
  "   → Visuel d'offre d'emploi prêt à publier. Ex: `gen recrutement: Développeur Full Stack Senior | CDI | Antananarivo | recrutement@nuklear.io`",
  "   → Contrat/lieu/email optionnels (valeurs par défaut Nuklear si omis).",
  "",
  "4️⃣ *actus* / *news*",
  "   → Actualités secteur + mouvements concurrents.",
  "",
  "5️⃣ *Pose n'importe quelle question* (marketing, growth, SEO, dev, data, IA...)",
  "   → Réponse en conversation libre, en tant qu'expert digital Nuklear. Ex: `Comment structurer une landing page qui convertit ?` La conversation garde le fil (mémoire des échanges précédents).",
  "",
  "6️⃣ *Envoie directement une image* (avec ou sans légende)",
  "   → Avis d'expert sur le visuel : ce qui marche, ce qui ne marche pas, recommandations concrètes. Fonctionne sur une création Nuklear, un brief client ou une pub concurrente.",
  "",
  "Après une proposition :",
  "   ✅ *ok* / *valide* → génère le visuel final",
  "   🔄 *encore* / *autre* → relance une recherche d'idées",
  "   ✏️ *affine: <remarque>* → ajuste l'idée",
].join("\n");

function stripPunct(s) {
  const t = s.replace(/[\s!.?,;]+$/, "");
  return t || s;
}

function detectPlatform(low) {
  const aliases = [["insta", "instagram"], ["instagram", "instagram"], ["ig", "instagram"], ["fb", "facebook"], ["facebook", "facebook"]];
  for (const [alias, canon] of aliases) {
    if (new RegExp("\\b" + alias + "\\b").test(low)) return canon;
  }
  return null;
}

function splitFreeText(t) {
  const i = t.indexOf(":");
  if (i === -1) return [t.trim(), ""];
  return [t.slice(0, i).trim(), t.slice(i + 1).trim()];
}

const raw = text.trim();
const norm = stripPunct(raw.toLowerCase()) || raw.toLowerCase();

let cmd = "unknown", platform = null, freeText = "";

if (["help", "aide", "?", "menu"].includes(norm)) cmd = "help";
else if (["ok", "valide", "validé", "go", "oui", "✅"].includes(norm)) cmd = "validate";
else if (["encore", "autre", "autres", "relance", "🔄", "non"].includes(norm)) cmd = "refresh";
else {
  const refineMatch = raw.match(/^(affine|adapte|change)\s*[:\-]\s*([\s\S]+)$/i);
  if (refineMatch) {
    cmd = "refine"; freeText = refineMatch[2].trim();
  } else {
    const [head, free] = splitFreeText(raw);
    const lowHead = head.toLowerCase();
    if (/\b(actus?|news|actualit)/.test(lowHead)) cmd = "news";
    else if (/\b(g[eé]n(?:e|è)re?|gen|cr[eé]e?)\b.*\b(recrutement|recrute|embauche)\b/.test(lowHead)) { cmd = "gen_recrutement"; freeText = free; }
    // Commandes FORCÉES : outrepassent la classification automatique du LLM pour donner un accès
    // direct et fiable à une catégorie précise (utile pour tester/forcer un format sans dépendre de
    // la détection automatique, qui peut varier selon l'idée synthétisée).
    else if (/\b(g[eé]n(?:e|è)re?|gen|cr[eé]e?)\b.*\b(collection)\b/.test(lowHead)) { cmd = "gen_collection"; platform = detectPlatform(lowHead); freeText = free; }
    else if (/\b(g[eé]n(?:e|è)re?|gen|cr[eé]e?)\b.*\b(avant.?apr[eè]s)\b/.test(lowHead)) { cmd = "gen_avant_apres"; platform = detectPlatform(lowHead); freeText = free; }
    else if (/\b(g[eé]n(?:e|è)re?|gen|cr[eé]e?)\b.*\b(annonce)\b/.test(lowHead)) { cmd = "gen_annonce"; platform = detectPlatform(lowHead); freeText = free; }
    else if (/\b(g[eé]n(?:e|è)re?|gen|cr[eé]e?)\b.*\bvid/.test(lowHead)) { cmd = "gen_video"; freeText = free; }
    else if (/\b(g[eé]n(?:e|è)re?|gen|cr[eé]e?)\b.*\b(image|visuel|post)/.test(lowHead)) {
      cmd = "gen_image"; platform = detectPlatform(lowHead); freeText = free;
    }
    // Repli : aucune commande reconnue -- au lieu d'un message d'erreur ("je ne comprends que..."),
    // le message est traité comme une VRAIE question posée à l'expert Nuklear (conversation libre,
    // voir Run Brain::buildExpertSystemPrompt). C'est le coeur de la fonctionnalité "conversation
    // réelle avec l'agent" : plus besoin d'apprendre une syntaxe de commande pour obtenir une réponse
    // utile. Un message vide (webhook Meta atypique) reste "unknown" -- rien de sensé à envoyer au LLM.
    else if (raw) { cmd = "chat"; freeText = raw; }
  }
}

// ============================================================================
// 5. Commandes "rapides" (aucun appel externe nécessaire) traitées directement ici.
// ============================================================================
if (cmd === "help") return [{ json: { sender, needsBrain: false, text: HELP_TEXT, image_url: null } }];
// N'arrive plus que sur un message réellement vide (payload webhook atypique) -- toute question ou
// remarque en texte libre part désormais en conversation ("chat"), voir plus haut.
if (cmd === "unknown") return [{ json: { sender, needsBrain: false, text: "Message vide. Tape *aide* pour voir les commandes, ou pose-moi directement une question.", image_url: null } }];
if (cmd === "validate" && state.stage !== "idea_proposed") return [{ json: { sender, needsBrain: false, text: "Rien à valider. Lance d'abord *gen image insta*.", image_url: null } }];
if (cmd === "refresh" && state.stage !== "idea_proposed") return [{ json: { sender, needsBrain: false, text: "Aucune idée en cours. Lance d'abord *gen image insta* ou *gen image facebook*.", image_url: null } }];
if (cmd === "refine" && state.stage !== "idea_proposed") return [{ json: { sender, needsBrain: false, text: "Aucune idée à affiner. Lance d'abord une génération d'image.", image_url: null } }];

// ============================================================================
// 6. Limite quotidienne (voir la fonction quotaExceeded, définie plus haut -- partagée avec la voie
//    image).
// ============================================================================
if (quotaExceeded(sender)) return [{ json: { sender, needsBrain: false, text: QUOTA_MESSAGE, image_url: null } }];

// ============================================================================
// 7. Tout le reste a besoin du cerveau (recherche + LLM + éventuellement image).
// ============================================================================
return [{ json: {
  sender, needsBrain: true, command: cmd,
  platform: platform || state.platform || "instagram",
  freeText, state,
} }];

// ============================================================================
// Config -- à remplacer avant activation.
// ============================================================================
const TAVILY_KEY = "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";
// Clé API Anthropic (console.anthropic.com -> API Keys). Aucune valeur par défaut fournie :
// le workflow refuse proprement (message WhatsApp explicite) tant qu'elle n'est pas renseignée,
// plutôt que d'échouer avec une 401 Anthropic cryptique.
const ANTHROPIC_KEY = "REPLACE_WITH_ANTHROPIC_API_KEY";
// Deux modèles, choisis pour la tâche -- pas "le plus gros partout" :
// - MODEL_FAST (Sonnet) : synthèse d'idée (JSON structuré), prompt vidéo -- rapide, excellent en
//   copywriting/créa, coût maîtrisé pour un usage à volume (plusieurs générations par commande).
// - MODEL_FALLBACK (Haiku) : filet de secours si Sonnet échoue -- rapide et fiable, jamais un échec
//   silencieux de bout en bout.
// - MODEL_EXPERT (Opus) : conversation experte en tête-à-tête (nouvelle fonctionnalité "chat") --
//   raisonnement le plus poussé, pour des réponses de qualité conseil senior, pas de la génération
//   de contenu à la chaîne.
const ANTHROPIC_MODEL_FAST = "claude-sonnet-5";
const ANTHROPIC_MODEL_FALLBACK = "claude-haiku-4-5";
const ANTHROPIC_MODEL_EXPERT = "claude-opus-5";
// Jeton d'accès Meta/WhatsApp Cloud API (le MÊME que celui déjà configuré dans le noeud "Send to
// WhatsApp" -- Bearer). Requis UNIQUEMENT pour la fonctionnalité "feedback créatif sur image" (elle
// doit télécharger l'image envoyée par l'équipe avant de l'analyser). Laissé sur le placeholder =
// la fonctionnalité répond proprement "jeton non configuré" au lieu d'échouer sans explication.
const WHATSAPP_TOKEN = "REPLACE_WITH_WHATSAPP_ACCESS_TOKEN";
const NUKLEAR_POSITIONING = "agence digitale (développement, design, marketing, growth, data, IA, SEO) -- l'extension digitale de ses clients";
const BRAND_VOICE = "humoristique, sarcastique, décontracté mais expert — jamais corporate-plat";
// Typographie de marque (charte Nuklear -- SFT Schrifted Sans, indisponible en génération -->
// substitut officiel : Inter). Police Google Fonts, résolue nativement par Cloudinary dans un
// calque l_text: -- aucun upload de fonte requis. Un seul point de vérité : changer la police de
// TOUS les visuels revient à changer cette seule constante.
const NK_FONT = "Inter";
// Historique de conversation ("chat" expert) : nombre de MESSAGES conservés (paires user/assistant),
// pas de tours -- borne le coût/latence des appels Anthropic sur les échanges longs.
const CHAT_HISTORY_MAX_MESSAGES = 16;
const CLOUDINARY_CLOUD = "pme0bbhb";
const LOGO_PUBLIC_ID = "Logo_gtorte";
// Icône [N] à poser À GAUCHE du wordmark ci-dessus (asset stocké, même cloud Cloudinary --
// aucune dépendance "Fetched URL"). Public_id extrait de l'URL fournie par l'utilisateur.
const MINILOGO_PUBLIC_ID = "MiniLogo_v6kxzf";
// ⚙️ Lueur de fond dégradée. DÉSACTIVÉE par défaut : le rendu par défaut redevient le poster épuré
// déjà validé. La v1 échouait car elle cumulait DEUX effets e_ dans un même composant Cloudinary
// (e_colorize + e_blur) -- interdit : un seul e_ par composant, sinon le flou est ignoré et le halo
// devient un RECTANGLE PLEIN. Syntaxe corrigée ci-dessous (un e_ par composant). À ne repasser à true
// qu'après avoir vérifié le rendu sur UNE génération de test.
const ENABLE_BRAND_GLOW = false;
// 🎨 FOND DÉGRADÉ DE MARQUE (celui fait sur Canva). Un lien de partage canva.link N'EST PAS une image
// et n'est pas lisible par Cloudinary : il faut EXPORTER le fond en PNG/JPG depuis Canva, puis
// l'uploader dans la Media Library Cloudinary, et coller ici son public_id (le nom affiché dans
// Cloudinary, ex: "Fond_degrade_nuklear"). Une fois renseigné, ce fond devient le CANEVAS du visuel
// (asset STOCKÉ -> aucune dépendance "Fetched URL"), recadré en 4:5. Laissé sur le placeholder =
// canevas noir uni actuel (comportement validé, inchangé).
// Si renseigné, ce public_id UNIQUE est TOUJOURS utilisé (utile pour figer/tester un fond précis) --
// prioritaire sur la bibliothèque ci-dessous. Placeholder = bibliothèque active.
const BRAND_BG_PUBLIC_ID = "REPLACE_WITH_BRAND_BG_PUBLIC_ID";
// 🎨 BIBLIOTHÈQUE de fonds dégradés "du même genre" : un fond DIFFÉRENT est utilisé à CHAQUE
// génération, dans un ordre FIXE et prévisible (rotation, pas tirage au sort -- voir
// nextInRotation) pour varier le visuel de façon maîtrisée tout en gardant la charte (dégradé sombre
// + anneau/forme). Pour ajouter un fond : exportez-le en PNG depuis Canva, ajoutez-le au dépôt GitHub
// (ex: fond2.png, fond3.png...), puis collez son URL brute ("raw.githubusercontent.com") ci-dessous --
// une ligne par fond. Chaque source est uploadée vers Cloudinary et mise en cache INDÉPENDAMMENT (une
// seule fois par source, $getWorkflowStaticData) : les exécutions suivantes ne re-téléchargent jamais
// un fond déjà connu, même si un AUTRE membre du tableau vient à son tour dans la rotation.
const BRAND_BG_SOURCES = [
  "https://raw.githubusercontent.com/Fihobiana87/Nuklear/main/fond.png",
  "https://raw.githubusercontent.com/Fihobiana87/Nuklear/main/fond2.png",
  "https://raw.githubusercontent.com/Fihobiana87/Nuklear/main/fond4.png",
  "https://raw.githubusercontent.com/Fihobiana87/Nuklear/main/fond5.png",
  "https://raw.githubusercontent.com/Fihobiana87/Nuklear/main/fond6.png",
  "https://raw.githubusercontent.com/Fihobiana87/Nuklear/main/fond7.png",
  // fond3.png EXCLU ICI : format PAYSAGE (720x392), utilisé par le pool dédié ci-dessous.
];
// Fond(s) dédiés au format PAYSAGE (catégorie "annonce", canevas 1080x588 -- même ratio que fond3.png,
// aucun recadrage nécessaire). Même mécanique de rotation + cache que le pool portrait, dans un
// tableau séparé car les deux formats ne sont PAS interchangeables.
const BRAND_BG_SOURCES_LANDSCAPE = [
  "https://raw.githubusercontent.com/Fihobiana87/Nuklear/main/fond3.png",
];
// Nom d'un "upload preset" Cloudinary en mode UNSIGNED (Settings > Upload > Upload presets).
// Sert au montage par UPLOAD (Cloudinary va chercher l'image lui-même, côté serveur), qui NE
// dépend PAS du réglage "Fetched URL" -- lequel est désactivé par défaut sur les comptes récents
// et bloque toute URL /image/fetch/ avec une 400 (cause racine du "montage indisponible"). Requis
// pour les fonds de marque ET les photos Pexels ; sans lui, ces deux chemins sont simplement
// sautés (voir presetOk / resolveBackgroundFromPool) et le rendu retombe sur le poster déterministe.
const CLOUDINARY_UPLOAD_PRESET = "nuklear_unsigned";
// ⭐ CHEMIN LE PLUS FIABLE ET LE PLUS FIDÈLE À LA CHARTE. public_id d'un FOND DE MARQUE vierge
// (le gabarit sombre Nuklear SANS texte : fond noir, dégradé orange/teal, logo, forme géométrique)
// uploadé une fois dans la Media Library Cloudinary. Si renseigné, le visuel = CE gabarit + l'accroche
// incrustée par-dessus. Comme c'est un asset STOCKÉ, sa livraison ne dépend NI du réglage "Fetched URL"
// NI d'un upload preset -> ça marche même quand tout le reste est bloqué. Laisser le placeholder =
// on retombe sur les fonds BRAND_BG_SOURCES (rotation) puis, en dernier recours, le poster déterministe.
const BRAND_TEMPLATE_PUBLIC_ID = "REPLACE_WITH_BRAND_TEMPLATE_PUBLIC_ID";
// Couleurs de marque Nuklear (utilisées pour la plaque de contraste et le badge de catégorie).
const BRAND_DARK = "040404";     // fond
const BRAND_ORANGE = "E23013";   // accent primaire
const BRAND_TEAL = "0E96A8";     // accent secondaire
const BRAND_SLOGAN = "Because what we do is mindblowing"; // slogan de marque, incrusté en bas-centre
// 📷 Banque de PHOTOS RÉELLES (Pexels, gratuit) pour ILLUSTRER l'idée SANS IA générative -> aucune
// image inventée, aucun faux texte incrusté (contrairement à un générateur d'image IA, écarté pour
// cette raison -- voir historique). Crée une clé gratuite sur https://www.pexels.com/api/ et colle-la
// ici. Laissé sur le placeholder = bascule propre sur le poster de marque déterministe.
const PEXELS_KEY = "mc14xFpLtRxzvgx7AxNAM2q1A12S4FGNjD7PvfwUaKm3z1nqdIsaflYc";
const COMPETITOR_CACHE_TTL_MS = 24 * 60 * 60 * 1000; // 24h -- les concurrents ne changent pas d'un message à l'autre

const item = $input.first().json;
const { sender, command, platform, freeText, state, imageId } = item;

const staticData = $getWorkflowStaticData('global');
staticData.sessions = staticData.sessions || {};
staticData.competitorsCache = staticData.competitorsCache || {};

// ============================================================================
// Helpers réseau (this.helpers.httpRequest -- natif n8n Code node).
// Un seul retry après échec réseau transitoire : Tavily/Anthropic peuvent
// avoir des blips passagers, un retry évite qu'un message WhatsApp entier
// échoue pour un simple timeout isolé.
// ============================================================================
async function httpRequestWithRetry(opts, retries) {
  try {
    return await this.helpers.httpRequest(opts);
  } catch (e) {
    if (retries > 0) {
      await new Promise(r => setTimeout(r, 500));
      return httpRequestWithRetry.call(this, opts, retries - 1);
    }
    throw e;
  }
}

async function tavilySearch(query, count) {
  try {
    const res = await httpRequestWithRetry.call(this, {
      method: "POST",
      url: "https://api.tavily.com/search",
      headers: { Authorization: `Bearer ${TAVILY_KEY}`, "Content-Type": "application/json" },
      body: { query, max_results: count },
      json: true,
      timeout: 15000,
    }, 1);
    return ((res && res.results) || []).map(r => ({ title: r.title, url: r.url, snippet: r.content }));
  } catch (e) { return []; }
}

// Recherche une PHOTO RÉELLE (Pexels) qui illustre l'idée. Renvoie une URL d'image directe (jpg) ou
// null. Orientation portrait pour coller au format 4:5. On pioche au hasard parmi les résultats pour
// varier le visuel d'une génération à l'autre (Math.random est OK dans un Code node n8n).
async function pexelsSearchPhoto(query) {
  if (!PEXELS_KEY || PEXELS_KEY.indexOf("REPLACE_WITH") !== -1) return null;
  const pick = async (q) => {
    try {
      const res = await httpRequestWithRetry.call(this, {
        method: "GET",
        url: `https://api.pexels.com/v1/search?query=${encodeURIComponent(q)}&orientation=portrait&per_page=12&size=large`,
        headers: { Authorization: PEXELS_KEY },
        json: true,
        timeout: 15000,
      }, 1);
      const photos = (res && res.photos) || [];
      if (!photos.length) return null;
      const p = photos[Math.floor(Math.random() * photos.length)];
      return (p && p.src && (p.src.portrait || p.src.large2x || p.src.large || p.src.original)) || null;
    } catch (e) { return null; }
  };
  // 1) requête riche (scène décrite par le LLM) ; 2) repli générique si aucun résultat.
  const short = String(query || "").split(/\s+/).slice(0, 6).join(" ").trim();
  return (await pick.call(this, short || "business marketing")) || (await pick.call(this, "modern business marketing office team"));
}

// Récupère une image WhatsApp ENTRANTE (envoyée par l'équipe) en base64, pour la fonctionnalité
// "feedback créatif sur image". Deux appels obligatoires côté API Meta Graph : (1) résoudre l'ID média
// (fourni par le webhook) en URL signée temporaire, (2) télécharger le binaire à cette URL -- les deux
// nécessitent le MÊME jeton d'accès que l'envoi de messages (WHATSAPP_TOKEN, voir tête de fichier).
// Ne lève JAMAIS : renvoie null en cas de jeton absent ou d'échec réseau, pour un repli propre côté
// WhatsApp plutôt qu'une exécution cassée.
async function fetchWhatsAppImageBase64(mediaId) {
  if (!WHATSAPP_TOKEN || WHATSAPP_TOKEN.indexOf("REPLACE_WITH") !== -1) return null;
  try {
    const meta = await httpRequestWithRetry.call(this, {
      method: "GET",
      url: `https://graph.facebook.com/v21.0/${mediaId}`,
      headers: { Authorization: `Bearer ${WHATSAPP_TOKEN}` },
      json: true,
      timeout: 15000,
    }, 1);
    if (!meta || !meta.url) return null;
    // encoding:null -> this.helpers.httpRequest renvoie le corps BRUT (Buffer), pas du texte/JSON --
    // nécessaire pour un binaire image. La réponse Graph API porte déjà le bon Content-Type (mime_type).
    const binary = await this.helpers.httpRequest({
      method: "GET",
      url: meta.url,
      headers: { Authorization: `Bearer ${WHATSAPP_TOKEN}` },
      encoding: null,
      timeout: 30000,
    });
    const buffer = Buffer.isBuffer(binary) ? binary : Buffer.from(binary);
    if (!buffer || !buffer.length) return null;
    return { base64: buffer.toString("base64"), mediaType: meta.mime_type || "image/jpeg" };
  } catch (e) { return null; }
}

function extractDomain(url) {
  if (!url || url.indexOf("://") === -1) return "";
  return url.split("://")[1].split("/")[0].replace(/^www\./, "");
}

// Plafond de collecte INTERNE (10), indépendant du maxResults de chaque appelant : synthesizeIdea
// demande 8, le handler "news" en demande 5 -- si on mettait en cache une liste tronquée à la
// taille du PREMIER appelant, un appel suivant qui en demande davantage serait silencieusement
// à court de résultats. On collecte toujours large, on tronque à la sortie selon l'appelant.
const COMPETITOR_COLLECT_CAP = 10;

async function discoverCompetitorsUncached(positioning) {
  const queries = [
    `agences concurrentes de ${positioning} Madagascar OR Afrique OR France`,
    `"${positioning}" alternative agency 2026`,
  ];
  let hits = [];
  for (const q of queries) hits = hits.concat(await tavilySearch.call(this, q, 10));
  const seen = new Set(); const profiles = [];
  for (const h of hits) {
    const domain = extractDomain(h.url);
    if (!domain || seen.has(domain) || domain.indexOf("nuklear") !== -1) continue;
    seen.add(domain);
    profiles.push({ name: h.title || domain, domain, snippet: h.snippet || "" });
    if (profiles.length >= COMPETITOR_COLLECT_CAP) break;
  }
  return profiles;
}

// Cache 24h : la découverte de concurrents coûte 2 requêtes Tavily -- sans cache, CHAQUE
// commande gen_image/gen_video/news relance cette découverte, épuisant vite le quota gratuit
// mensuel partagé par toute l'équipe (1000 req/mois Tavily).
async function discoverCompetitors(positioning, maxResults) {
  const cached = staticData.competitorsCache[positioning];
  if (cached && (Date.now() - cached.ts) < COMPETITOR_CACHE_TTL_MS) {
    return cached.data.slice(0, maxResults);
  }
  const data = await discoverCompetitorsUncached.call(this, positioning);
  staticData.competitorsCache[positioning] = { ts: Date.now(), data };
  return data.slice(0, maxResults);
}

// Schéma strict de l'idée créative : garantit une réponse JSON valide et complète (Anthropic
// structured outputs -- output_config.format) plutôt que de parser un texte libre au hasard.
// Supprime toute une classe de bugs passés ("le LLM a renvoyé du JSON mal formé/tronqué") --
// plus besoin d'extraction par regex ni de tolérance aux fautes de syntaxe du modèle.
// additionalProperties:false exige que CHAQUE clé soit dans "required" (contrainte des structured
// outputs) ; les champs non pertinents pour une catégorie donnée (ex: body_lines hors "annonce")
// sont simplement renvoyés vides ("" ou []) -- déjà le comportement attendu par buildIdeaFromData.
const IDEA_JSON_SCHEMA = {
  type: "object",
  properties: {
    hook: { type: "string" },
    kicker: { type: "string" },
    caption: { type: "string" },
    hashtags: { type: "array", items: { type: "string" } },
    visual_subject: { type: "string" },
    visual_subject_before: { type: "string" },
    visual_subject_after: { type: "string" },
    visual_subjects: { type: "array", items: { type: "string" } },
    body_lines: { type: "array", items: { type: "string" } },
    visual_style: { type: "string", enum: ["cinematic photograph", "modern 3D render", "editorial digital illustration"] },
    tone: { type: "string" },
    category: { type: "string", enum: ["astuce", "collection", "avant_apres", "annonce"] },
    confidence: { type: "number" },
  },
  required: ["hook", "kicker", "caption", "hashtags", "visual_subject", "visual_subject_before",
    "visual_subject_after", "visual_subjects", "body_lines", "visual_style", "tone", "category", "confidence"],
  additionalProperties: false,
};

// Appel Messages API Anthropic. `messages` est déjà au format [{role, content}, ...] (permet de
// réutiliser cette fonction aussi bien pour un tour unique -- idée, prompt vidéo -- que pour une
// conversation multi-tours -- le mode "chat" expert). `jsonSchema` bascule sur les structured
// outputs (sortie garantie conforme au schéma) ; sans lui, réponse texte libre.
async function anthropicComplete(model, system, messages, options) {
  const opts = options || {};
  if (!ANTHROPIC_KEY || ANTHROPIC_KEY.indexOf("REPLACE_WITH") !== -1) {
    throw new Error("Clé Anthropic non configurée (ANTHROPIC_KEY).");
  }
  const body = { model, max_tokens: opts.maxTokens || 1024, system, messages };
  const outputConfig = {};
  if (opts.effort) outputConfig.effort = opts.effort;
  if (opts.jsonSchema) outputConfig.format = { type: "json_schema", schema: opts.jsonSchema };
  if (Object.keys(outputConfig).length) body.output_config = outputConfig;
  const res = await httpRequestWithRetry.call(this, {
    method: "POST",
    url: "https://api.anthropic.com/v1/messages",
    headers: {
      "x-api-key": ANTHROPIC_KEY,
      "anthropic-version": "2023-06-01",
      "content-type": "application/json",
    },
    body,
    json: true,
    timeout: 120000,
  }, 1);
  if (res.stop_reason === "refusal") {
    throw new Error(`Anthropic a refusé la requête${res.stop_details && res.stop_details.category ? ` (${res.stop_details.category})` : ""}.`);
  }
  const textBlock = (res.content || []).find(b => b.type === "text");
  return textBlock ? textBlock.text : "";
}

// Synthèse d'idée : structured outputs -> le texte renvoyé est TOUJOURS un JSON valide conforme à
// IDEA_JSON_SCHEMA (garanti par l'API, pas par un espoir de formatage correct du modèle). Repli sur
// MODEL_FALLBACK (Haiku) si Sonnet échoue (surcharge, réseau) -- jamais d'échec silencieux.
async function completeJson(system, user) {
  const messages = [{ role: "user", content: user }];
  try {
    const rawText = await anthropicComplete.call(this, ANTHROPIC_MODEL_FAST, system, messages, { jsonSchema: IDEA_JSON_SCHEMA, effort: "high" });
    return JSON.parse(rawText);
  } catch (e) {
    try {
      const rawText = await anthropicComplete.call(this, ANTHROPIC_MODEL_FALLBACK, system, messages, { jsonSchema: IDEA_JSON_SCHEMA, effort: "high" });
      return JSON.parse(rawText);
    } catch (e2) { return null; }
  }
}

function safeFloat(v, def) {
  const f = parseFloat(v);
  return Number.isFinite(f) ? f : def;
}

// ============================================================================
// Synthèse d'idée virale (LLM avec repli heuristique déterministe -- jamais
// d'échec silencieux : si Anthropic tombe, une idée cohérente sort quand même).
// ============================================================================
async function synthesizeIdea(platformArg, hint, previousIdea, forcedCategory) {
  const competitors = await discoverCompetitors.call(this, NUKLEAR_POSITIONING, 8);
  const trendHits = await tavilySearch.call(this, `contenu viral marketing agence ${platformArg} tendance 2026 humour`, 15);
  let competitorHits = [];
  for (const c of competitors.slice(0, 5)) {
    competitorHits = competitorHits.concat(await tavilySearch.call(this, `site:${c.domain} ${platformArg}`, 3));
  }

  let system = `Tu es directeur artistique ET copywriter de Nuklear (agence marketing/growth/SEO). Ton de marque : ${BRAND_VOICE}. Tu conçois UN visuel social VIRAL, digne d'un grand designer, prêt à publier. L'idée doit être CLAIRE, SIMPLE et INTÉRESSANTE : un angle fort compréhensible en 2 secondes, tiré des mécaniques les plus virales (astuce contre-intuitive, erreur #1 courante, secret/coulisses, chiffre choc, avant/après, mythe vs réalité, "personne ne te dit que..."). Réponds UNIQUEMENT en JSON avec EXACTEMENT ces clés :
- "hook" : l'accroche AFFICHÉE sur le visuel, EN FRANÇAIS PARFAIT (zéro faute), courte et percutante, ≤ 10 mots.
- "kicker" : 1 à 3 MOTS-CLÉS EN FRANÇAIS EN MAJUSCULES (le thème, ex: "SEO LOCAL", "ERREUR #1", "ASTUCE PRO"). Étiquette courte.
- "caption" : la LÉGENDE du post, EN FRANÇAIS, 1 à 3 phrases, ton Nuklear (simple, drôle, amical MAIS pro), qui développe l'idée et invite à agir/commenter. 1 emoji max, à la fin.
- "hashtags" : un tableau de 6 à 9 hashtags PERTINENTS et POPULAIRES (mélange large + niche marketing/SEO/réseaux sociaux), en minuscules, sans espace, chacun commençant par #.
- "visual_subject" : EN ANGLAIS, une SCÈNE riche, concrète et cinématographique qui illustre l'idée (peut inclure des PERSONNES RÉALISTES, un décor, une situation ; JAMAIS une icône plate). Ex: "a focused young entrepreneur working late at a glowing laptop in a cozy creative studio". AUCUN texte dans la description.
- "visual_subject_before" / "visual_subject_after" : UNIQUEMENT si category="avant_apres" -- EN
  ANGLAIS, DEUX scènes concrètes et cinématographiques montrant l'état "avant" (le problème) et
  l'état "après" (le résultat), MAIS avec le MÊME décor/personnage/contexte de base -- seul l'état
  change (ex: "a cluttered messy desk with old paperwork" / "the same desk, now clean and organized
  with a laptop"). PAS deux scènes sans rapport. Sinon, laisser vide.
- "visual_subjects" : UNIQUEMENT si category="collection" -- un TABLEAU de 4 scènes EN ANGLAIS, concrètes et DISTINCTES (chacune illustre un élément différent), MAIS COHÉRENTES ENTRE ELLES : même
  décor/équipe/ambiance/lumière d'une scène à l'autre (ex: le même bureau, la même équipe, à des
  moments différents), PAS 4 scènes sans rapport -- pour que les 4 photos se ressemblent visuellement
  une fois assemblées. Sinon, laisser vide ([]).
- "body_lines" : UNIQUEMENT si category="annonce" -- un TABLEAU de 2 à 4 lignes COURTES (≤ 60
  caractères chacune) EN FRANÇAIS, les informations factuelles à communiquer (ex: date, lieu, détail
  pratique, bénéfice clé). Sinon, laisser vide ([]).
- "visual_style" : EN ANGLAIS, exactement l'un de : "cinematic photograph", "modern 3D render", "editorial digital illustration".
- "tone" : EN FRANÇAIS (ex: "humoristique", "inspirant", "expert").
- "category" : réfléchis activement aux QUATRE options ci-dessous avant de choisir -- ne choisis PAS
  automatiquement la première par habitude, chacune est aussi valide que les autres selon l'idée :
  * "astuce" : UN conseil/erreur/mythe/chiffre choc, un seul visuel + une photo.
  * "collection" : PLUSIEURS éléments/services/exemples à présenter ensemble (l'idée liste ou compare
    plusieurs choses -- ex: "3 astuces pour...", "nos services", "les erreurs les plus courantes").
  * "avant_apres" : une transformation/un résultat avant vs après (l'idée décrit un changement dans le
    temps, un état "avant" et un état "après" distincts -- ex: "de 0 à 40 leads", "avant/après refonte").
  * "annonce" : une ANNONCE avec PLUSIEURS informations factuelles à communiquer (événement, ouverture,
    changement, mise à jour, offre d'emploi générale...) -- choisis ce type dès que l'idée a besoin de
    plusieurs points détaillés (date, lieu, condition...) plutôt qu'une seule accroche courte.
  Écris EXACTEMENT l'un de ces 4 mots, en minuscules, SANS accent, SANS espace : astuce / collection /
  avant_apres / annonce (underscore, pas de tiret ni d'espace pour avant_apres).
- "confidence" : nombre 0 à 1.

RÈGLE ABSOLUE : l'accroche ET la légende doivent toujours être CLAIRES et SIGNIFIANTES pour un public
marketing/SEO -- JAMAIS une image ou une phrase absurde/surréaliste sans lien logique avec un vrai sujet
(ex à NE JAMAIS faire : "Logo sur la tête", ou toute juxtaposition bizarre de mots qui ne veut rien dire).
Chaque idée doit pouvoir se résumer en une phrase compréhensible par un humain en 2 secondes.
Exemples d'accroches VALIDES (ton, longueur, clarté à respecter) :
- "L'erreur SEO n°1 : ignorer la vitesse de chargement"
- "80% des clics restent sur la première page Google"
- "Un site sans bouton d'action, c'est un vendeur muet"
Exemples INVALIDES (à ne jamais produire, trop vagues/absurdes/fragmentaires) :
- "Logo sur la tête", "Marketing bizarre", "Astuce", "SEO ?!"`;
  if (previousIdea) system += " Une idée a DÉJÀ été proposée, l'équipe demande un AJUSTEMENT -- garde le même angle sauf si la remarque dit le contraire.";
  // Commande FORCÉE (gen collection / gen avant apres / gen annonce) : la catégorie est déjà connue,
  // pas besoin de la déduire -- mais il faut prévenir le LLM pour qu'il remplisse les champs
  // spécifiques à CETTE catégorie (visual_subjects / visual_subject_before+after / body_lines),
  // sinon ils restent vides et le rendu utilise un repli générique moins riche.
  if (forcedCategory) system += ` IMPORTANT : category DOIT être exactement "${forcedCategory}" -- remplis bien les champs spécifiques à cette catégorie en conséquence.`;

  const trends = trendHits.slice(0, 12).map(h => `- ${h.title}: ${h.snippet}`).join("\n");
  const comps = competitorHits.slice(0, 10).map(h => `- ${h.title}: ${h.snippet}`).join("\n");
  let previousBlock = "";
  if (previousIdea) previousBlock = `\nIdée précédemment proposée (à AJUSTER) :\n- Accroche: ${previousIdea.hook}\n- Concept: ${previousIdea.visual_concept}\n- Ton: ${previousIdea.tone}\n`;
  const user = `Plateforme cible : ${platformArg}\nConsigne équipe : ${hint || "(aucune)"}\n${previousBlock}\nTendances:\n${trends || "(rien)"}\n\nConcurrents:\n${comps || "(rien)"}\n\nPropose la meilleure idée.`;

  const sources = [...trendHits, ...competitorHits].map(h => h.url).filter(Boolean).slice(0, 5);
  const DEFAULT_TAGS = ["#marketingdigital", "#reseauxsociaux", "#growthhacking", "#seo", "#communitymanager", "#contentmarketing", "#nuklear"];

  function buildIdeaFromData(data) {
    if (!data) return null;
    return {
      hook: String(data.hook || "").trim(),
      kicker: String(data.kicker || data.tone || "NUKLEAR").toUpperCase().slice(0, 26),
      caption: String(data.caption || "").trim(),
      hashtags: cleanHashtags(data.hashtags, DEFAULT_TAGS),
      visual_subject: String(data.visual_subject || data.illustration_subject || "").trim(),
      visual_style: String(data.visual_style || "editorial digital illustration"),
      visual_concept: String(data.visual_concept || data.visual_subject || ""),
      format: String(data.format || "post"),
      tone: String(data.tone || "humoristique"),
      category: normalizeCategory(data.category),
      visual_subject_before: String(data.visual_subject_before || "").trim(),
      visual_subject_after: String(data.visual_subject_after || "").trim(),
      visual_subjects: Array.isArray(data.visual_subjects) ? data.visual_subjects.map(s => String(s || "").trim()).filter(Boolean).slice(0, 4) : [],
      body_lines: Array.isArray(data.body_lines) ? data.body_lines.map(s => String(s || "").trim()).filter(Boolean).slice(0, 4) : [],
      inspired_by: sources,
      confidence: safeFloat(data.confidence, 0.8),
    };
  }

  // ============================================================================
  // GARDE-FOU QUALITÉ : une idée vide, trop fragmentaire, absurde (simple écho du
  // kicker) ou sans légende ne part JAMAIS en publication. Un seul essai
  // supplémentaire avec instruction corrective si l'idée échoue le contrôle ;
  // sinon repli sur le CATALOGUE CURATED (jamais du texte scrapé au hasard).
  // ============================================================================
  let idea = buildIdeaFromData(await completeJson.call(this, system, user));
  if (!idea || isWeakIdea(idea)) {
    const correctiveSystem = system + "\n\nATTENTION : ta précédente proposition était trop vague, trop courte, ou incohérente (accroche absurde/sans lien clair avec un vrai sujet marketing/SEO, ou légende manquante). Cette fois, propose une accroche COMPLÈTE (au moins 4-5 mots) sur un VRAI angle marketing/SEO reconnaissable, et une légende développée, distincte de l'accroche.";
    const retryIdea = buildIdeaFromData(await completeJson.call(this, correctiveSystem, user));
    idea = (retryIdea && !isWeakIdea(retryIdea)) ? retryIdea : null;
  }
  if (idea) return idea;

  if (previousIdea) {
    return {
      hook: previousIdea.hook,
      kicker: previousIdea.kicker || "NUKLEAR",
      caption: previousIdea.caption || `${previousIdea.hook} — on t'explique. 🚀`,
      hashtags: (previousIdea.hashtags && previousIdea.hashtags.length) ? previousIdea.hashtags : DEFAULT_TAGS,
      visual_subject: previousIdea.visual_subject || "a modern minimal marketing scene",
      visual_style: previousIdea.visual_style || "editorial digital illustration",
      visual_concept: hint ? `${previousIdea.visual_concept} — ajustement demandé: ${hint}` : previousIdea.visual_concept,
      format: previousIdea.format, tone: previousIdea.tone,
      category: normalizeCategory(previousIdea.category),
      inspired_by: sources.length ? sources : previousIdea.inspired_by, confidence: 0.65,
    };
  }
  // LLM indisponible ou toujours incohérent après retry : on NE renvoie JAMAIS un titre scrapé au
  // hasard (source #1 des idées qui "ne veulent rien dire"). On pioche dans un catalogue d'idées
  // marketing/SEO écrites à la main, toujours claires, toujours publiables.
  return pickCuratedFallback(platformArg, hint, sources, DEFAULT_TAGS);
}

// Détecte une idée FAIBLE (vide, fragmentaire, absurde ou sous-déterminée) -- contrôle purement
// local (aucun appel réseau) déclenché après CHAQUE synthèse LLM, avant qu'une idée parte en
// publication. Volontairement généraliste (pas calé sur un cas précis) pour couvrir les principales
// classes d'échec observées : accroche vide/tronquée, simple écho du kicker, légende manquante ou
// dupliquée, sujet visuel resté sur le repli générique interne (signe que le LLM n'a rien fourni).
// Normalise la catégorie renvoyée par le LLM (ou par une idée précédente) sur les 3 valeurs connues.
// Toute valeur inattendue retombe sur "astuce" (le template le plus simple/robuste) plutôt que de
// planter ou de router vers un builder inexistant.
// Normalisation TOLÉRANTE : un petit modèle LLM n'écrit pas toujours "avant_apres" au caractère près
// (accents, tirets, espaces au lieu d'underscore sont naturels en français -- ex "avant-après",
// "avant après", "Avant/Après"). Une comparaison stricte (===) faisait silencieusement retomber TOUTE
// variante orthographique sur "astuce", donnant l'impression que seules des astuces étaient générées.
// On normalise (accents retirés, séparateurs uniformisés) AVANT de comparer.
function normalizeCategory(cat) {
  const c = String(cat || "")
    .toLowerCase()
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "") // retire les accents (é -> e, etc.)
    .trim()
    .replace(/[\s\-\/]+/g, "_"); // espaces/tirets/slash -> underscore
  if (c === "collection") return "collection";
  if (c === "avant_apres" || c === "avantapres") return "avant_apres";
  if (c === "annonce") return "annonce";
  return "astuce";
}

function isWeakIdea(idea) {
  const hook = String(idea.hook || "").trim();
  const words = hook.split(/\s+/).filter(Boolean);
  if (!hook || words.length < 3 || hook.length > 90) return true;
  if (idea.kicker && hook.toLowerCase() === String(idea.kicker).toLowerCase()) return true;
  const caption = String(idea.caption || "").trim();
  if (!caption || caption.length < 15 || caption.toLowerCase() === hook.toLowerCase()) return true;
  const subject = String(idea.visual_subject || "").trim().toLowerCase();
  if (!subject || subject === "a modern minimal marketing scene") return true;
  // Une accroche qui se termine par un nombre ISOLÉ ("... pour nos 4") ressemble fortement à une
  // énumération tronquée (le nom qui devait suivre le chiffre a disparu) -- repéré sur un rendu réel
  // (catégorie collection : "Un seul visuel pour nos 4" au lieu de "... nos 4 services").
  if (/\b\d+$/.test(hook.trim())) return true;
  return false;
}

// Catalogue d'idées marketing/SEO écrites À LA MAIN : dernier filet quand le LLM est indisponible ou
