    caption: "Vos visiteurs ne devinent pas ce qu'ils doivent faire. Un call-to-action clair, et tout change. 🎯",
    visual_subject: "a modern landing page mockup on a tablet screen with a bright clear call-to-action button, held by a marketer" },
  { hook: "Plus de mots-clés ne veut pas dire plus de trafic", kicker: "MYTHE VS RÉALITÉ", tone: "humoristique",
    caption: "Le bourrage de mots-clés, c'est fini depuis longtemps. Google préfère un contenu utile à un contenu répété. 😉",
    visual_subject: "a content writer crossing out repetitive keywords on a printed article with a red pen" },
  { hook: "80% des clics restent sur la première page Google", kicker: "CHIFFRE CHOC", tone: "expert",
    caption: "Si vous n'êtes pas en page 1, vous êtes presque invisible. Le SEO n'est pas un bonus, c'est une nécessité. 📈",
    visual_subject: "a laptop screen showing a Google search results page, close up, shallow depth of field" },
  { hook: "Une landing page lente perd 7% de vos conversions", kicker: "CHIFFRE CHOC", tone: "expert",
    caption: "Chaque seconde de chargement en trop, c'est de l'argent qui part. On optimise ça ensemble ? 💸",
    visual_subject: "a stopwatch next to a laptop displaying a website loading spinner, dramatic office lighting" },
  { hook: "Le contenu recyclé est votre meilleur allié SEO", kicker: "ASTUCE PRO", tone: "inspirant",
    caption: "Pas besoin de tout réinventer : un vieil article optimisé peut redevenir un aimant à trafic. ♻️",
    visual_subject: "a content marketer updating an old blog post on a laptop, sticky notes and a coffee cup on the desk" },
  { hook: "Avant : 0 appel entrant. Après : 40 par mois", kicker: "AVANT / APRÈS", tone: "inspirant",
    caption: "C'est la différence entre un site vitrine et un site qui vend vraiment. Voilà ce que fait une vraie stratégie growth. 🔥",
    visual_subject: "a small business owner smiling while looking at a ringing phone and a busy calendar on the desk" },
  { hook: "Le SEO local commence par votre fiche Google", kicker: "ASTUCE LOCALE", tone: "expert",
    caption: "Avant de penser au national, assurez-vous d'être visible à côté de chez vous. Ça change tout. 📍",
    visual_subject: "a local shop owner updating their business profile on a smartphone, storefront visible in the background" },
