function buildTemplateTiers(hook) {
  if (!BRAND_TEMPLATE_PUBLIC_ID || BRAND_TEMPLATE_PUBLIC_ID.indexOf("REPLACE_WITH") !== -1) return [];
  const t = encodeOverlayText(hook);
  const base = BRAND_TEMPLATE_PUBLIC_ID; // asset stocké : un "/" de dossier est OK en fin d'URL
  const root = `https://res.cloudinary.com/${CLOUDINARY_CLOUD}/image/upload`;
  // L'accroche en gros, blanc, sur une plaque sombre pour rester lisible quelle que soit la zone du
  // gabarit. Placement par défaut au centre -- affinable précisément une fois le gabarit connu.
  const textLayer = `l_text:${NK_FONT}_64_bold:${t},co_white,c_fit,w_880,g_center,y_0,b_rgb:${BRAND_DARK}cc`;
