// Encode une accroche pour un GROS titre (typo principale du gabarit) : lignes courtes, jusqu'à 5,
// adaptées à une grande taille de police.
function encodeHeadline(hook) {
  const cleaned = stripForOverlay(hook) || "Nuklear";
  const caption = cleaned.length > 160 ? cleaned.slice(0, 159) + "…" : cleaned;
  const lines = wrapCaption(caption, 16).slice(0, 5);
  return lines.map(l => encodeURIComponent(l).replace(/%2C/g, "%252C").replace(/%2F/g, "%252F")).join("%0A");
}

// MISE EN PAGE ÉDITORIALE "3 BANDES" sur une PHOTO RÉELLE (asset stocké) : bandeau sombre (logo) /
// FENÊTRE PHOTO plein largeur / pied sombre (kicker orange + H1 + slogan). TOUT le texte est sur du
// NOIR PLEIN -> lisibilité garantie, et la photo reste une fenêtre nette et non obstruée. Aucun
// dégradé/ombre fragile. Base = logo colorisé en canevas sombre (même socle éprouvé que le poster).
function buildPhotoEditorialTiers(photoPublicId, idea, bgId) {
  const W = 1080, H = 1350, M = PORTRAIT_MARGIN;
  const root = `https://res.cloudinary.com/${CLOUDINARY_CLOUD}/image/upload`;
  const { base, canvas } = canvasBase(W, H, bgId); // fond dégradé si dispo, sinon noir uni -- 4:5
  const kicker = encodeURIComponent(String(idea.kicker || "NUKLEAR").toUpperCase()).replace(/%2C/g, "%252C").replace(/%2F/g, "%252F");
  const slogan = encodeURIComponent(BRAND_SLOGAN).replace(/%2C/g, "%252C").replace(/%2F/g, "%252F");
  const photoLayerId = String(photoPublicId).replace(/\//g, ":");
  // ============================================================================================
  // MISE EN PAGE V2 : texte AU-DESSUS (bandeau haut), PHOTO GRANDE ET IMMERGÉE dessous, slogan tout
  // en bas. Remplace l'ancienne version qui calait un petit cercle pile sur l'anneau d'UN fond.png
  // précis (fragile dès que plusieurs fonds différents entrent en rotation, et jugée trop petite).
  // Ici la photo occupe la majorité du canevas (calcul ci-dessous), avec vignette + grading pour se
  // fondre dans N'IMPORTE quel fond sombre de la même famille, sans dépendre des coordonnées exactes
  // d'un anneau précis -- robuste face à une bibliothèque de fonds qui varie à chaque génération.
  // Marges vérifiées : bandeau (logo+kicker+H1) se termine à y=510 ; photo 565->1225 (55px de marge
  // au-dessus, 53px avant le slogan à y=1278) ; H1 en c_fit (h_280) donc jamais de débordement même
  // si l'accroche est longue -- le texte rétrécit pour tenir, il ne déborde jamais.
  // ============================================================================================
  const t = encodeHeadline(idea.hook);
  // Traitement photo partagé (PHOTO_GRADE, voir photoLayer()) + une variante de forme selon le fond :
  // médaillon circulaire liseré (r_max) quand un fond de marque est actif -- cohérent avec le cercle
  // de la maquette de référence -- sinon bande plein cadre (aucun liseré/radius : elle touche les
  // bords du canevas). Les deux gardent un léger vignettage pour fondre les bords dans le fond sombre.
  const photo = bgId
    ? `l_${photoLayerId}/c_fill,w_660,h_660,g_auto,r_max,${PHOTO_BORDER}/${PHOTO_GRADE}/e_vignette:35/fl_layer_apply,g_north_west,x_210,y_565`
    : `l_${photoLayerId}/c_fill,w_${W},h_680,g_auto/${PHOTO_GRADE}/e_vignette:40/fl_layer_apply,g_north,y_565`;
  const glow = brandGlowLayers(); // [] si désactivée
  const [miniLayer, wordLayer] = logoLockupLayers(M, 52, LOGO_HEIGHT_PHOTO);
  const kickerLayer = `l_text:${NK_FONT}_${KICKER_SIZE}_bold:${kicker},co_rgb:${BRAND_ORANGE}/fl_layer_apply,g_north_west,x_${M + 2},y_170`;
  const titleLayer = `l_text:${NK_FONT}_66_bold:${t},co_white,c_fit,w_${W - 2 * M},h_280/fl_layer_apply,g_north_west,x_${M},y_230`;
  const sloganLayer = `l_text:${NK_FONT}_${SLOGAN_SIZE}_bold:${slogan},co_white,e_shadow:90/fl_layer_apply,g_south,y_${M}`;
  const finish = "q_auto:best";
  const full = [canvas, photo, ...glow, miniLayer, wordLayer, kickerLayer, titleLayer, sloganLayer, finish].join("/");
  const noKicker = [canvas, photo, ...glow, miniLayer, wordLayer, titleLayer, sloganLayer, finish].join("/");
  // Filet ULTRA-SÛR : mêmes assets, SANS lueur.
  const bare = [canvas, photo, miniLayer, wordLayer, titleLayer, finish].join("/");
  return [
    { label: "photo éditoriale", url: `${root}/${full}/${base}` },
    { label: "photo + titre", url: `${root}/${noKicker}/${base}` },
    { label: "photo simple", url: `${root}/${bare}/${base}` },
  ];
}

