// Upload UNSIGNED depuis une URL distante : Cloudinary récupère l'image LUI-MÊME côté serveur
// pendant l'upload (indépendant du réglage fetch de livraison). Renvoie le public_id, ou null.
async function cloudinaryUploadFromUrl(sourceUrl) {
  // IMPORTANT : l'API d'upload Cloudinary attend du FORM-urlencoded, PAS du JSON. Envoyer du JSON
  // (json:true) fait échouer l'upload ("Missing required parameter - file"). On envoie donc un corps
  // application/x-www-form-urlencoded et on parse la réponse JSON à la main.
  const body = `file=${encodeURIComponent(sourceUrl)}&upload_preset=${encodeURIComponent(CLOUDINARY_UPLOAD_PRESET)}`;
  const res = await this.helpers.httpRequest({
    method: "POST",
    url: `https://api.cloudinary.com/v1_1/${CLOUDINARY_CLOUD}/image/upload`,
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body,
    json: false,
    timeout: 90000,
  });
  let data = res;
  if (typeof res === "string") { try { data = JSON.parse(res); } catch (e) { data = {}; } }
  return (data && data.public_id) ? data.public_id : null;
}

// Extrait la vraie cause d'un échec httpRequest : Cloudinary la met dans l'en-tête x-cld-error,
// n8n dans e.message ("400 - ...") ou e.response. On la remonte jusqu'au message WhatsApp pour ne
// plus jamais diagnostiquer à l'aveugle.
// Essaie une liste de crans dans l'ordre ; renvoie le PREMIER qui répond 2xx (this.helpers.httpRequest
// -- contexte n8n). Utilisé par "validate" (astuce/collection/avant_apres) ET par la commande
// recrutement -- factorisé pour ne pas dupliquer la logique de repli entre les deux.
async function tryTiers(tiers) {
  const errors = [];
  for (const tier of tiers) {
    try {
      await this.helpers.httpRequest({ method: "GET", url: tier.url, timeout: 30000, json: false });
      return { tier, errors };
    } catch (e) { errors.push(`${tier.label} → ${extractHttpError(e)}`); }
  }
  return { tier: null, errors };
}

function extractHttpError(e) {
  const resp = e && e.response;
  const hdr = (resp && (resp.headers || {})) || {};
  const cld = hdr["x-cld-error"] || hdr["X-Cld-Error"];
  if (cld) return String(cld).slice(0, 200);
  if (e && e.message) return String(e.message).slice(0, 200);
  return String(e).slice(0, 200);
}

// ============================================================================
// Conversation experte -- partagée par DEUX fonctionnalités : "chat" (n'importe quelle question posée
// en texte libre) et "vision" (feedback sur une image envoyée). Au lieu de se limiter à des commandes
// figées (gen image, gen video...), l'équipe peut consulter Nuklear en tant qu'expert digital senior
// (marketing, growth, SEO, dev, data, IA, design) et obtenir une vraie réponse de conseil. Modèle le
// plus capable (Opus) sur les deux : juger un visuel ou conseiller en profondeur demande le même niveau
// de raisonnement, contrairement à la synthèse d'idée (JSON structuré, Sonnet suffit largement).
// ============================================================================
function buildExpertSystemPrompt() {
  return `Tu es l'assistant IA interne de Nuklear, ${NUKLEAR_POSITIONING} — la signature de marque est "Because what we do is mindblowing".
Tu es un expert senior, polyvalent sur tous les sujets digitaux : marketing, growth, SEO, développement web/app, design produit, data, IA. Ton de voix Nuklear : ${BRAND_VOICE}.
Consignes :
- Réponds toujours en français, de façon experte, concrète et actionnable -- jamais de banalités ni de blabla générique de type "il est important de...".
- Format WhatsApp : phrases courtes, listes à puces si utile pour structurer, emojis avec parcimonie (jamais plus de 2-3 par message). Va droit au but : la réponse d'abord, le développement ensuite si nécessaire.
- Si la question sort du champ digital/marketing, réponds quand même utilement -- tu n'es pas limité à un seul sujet.
- N'invente JAMAIS un chiffre précis (statistique, prix, date, pourcentage) que tu ne connais pas avec certitude -- reste sur des ordres de grandeur, ou dis explicitement que ça dépend du contexte du client.
- Si on te montre une image, analyse-la vraiment (composition, lisibilité, hiérarchie, message, cohérence de marque) -- pas de généralités passe-partout applicables à n'importe quel visuel.`;
}

// ============================================================================
// Routage par commande.
// ============================================================================
let result = { sender, text: "Commande non reconnue. Tape *aide*.", image_url: null };

if (command === "news") {
  const sectorHits = await tavilySearch.call(this, `actualités ${NUKLEAR_POSITIONING} 2026`, 8);
  const competitors = await discoverCompetitors.call(this, NUKLEAR_POSITIONING, 5);
  let lines = ["📰 *Veille Nuklear*\n"];
  for (const h of sectorHits) lines.push(`📈 secteur — ${h.title}\n${h.url}`);
  for (const c of competitors.slice(0, 5)) {
    const hits = await tavilySearch.call(this, `${c.name} actualité annonce 2026`, 2);
    for (const h of hits) lines.push(`🏢 concurrent — ${h.title}\n${h.url}`);
  }
  result.text = lines.length > 1 ? lines.join("\n\n") : "Aucune actualité pertinente trouvée pour le moment.";
}

else if (command === "chat") {
  // Historique multi-tours, borné à CHAT_HISTORY_MAX_MESSAGES (voir en tête de fichier) -- indispensable
  // pour une VRAIE conversation (le modèle doit se souvenir des échanges précédents), mais sans laisser
  // grossir indéfiniment le coût/latence d'un appel Anthropic sur une conversation qui traîne en longueur.
  const history = Array.isArray(state.chat_history) ? state.chat_history : [];
  // ANCRAGE FACTUEL : une recherche Tavily légère sur la question posée donne au modèle des éléments
  // RÉCENTS à citer (actualité, tendance, chiffre) au lieu de raisonner seul sur des connaissances
  // figées à l'entraînement -- une vraie réponse d'expert s'appuie sur ce qui se passe MAINTENANT, pas
  // uniquement sur la mémoire du modèle. Injecté SEULEMENT dans le message envoyé à l'API, jamais dans
  // l'historique STOCKÉ (sinon chaque tour suivant réinjecterait le contexte du tour précédent, gonflant
  // les tokens pour rien -- ce contexte n'est utile qu'au moment précis où la question est posée).
  let groundingBlock = "";
  try {
    const hits = await tavilySearch.call(this, freeText, 5);
    if (hits.length) {
      groundingBlock = "\n\n[Contexte web récent -- à utiliser SEULEMENT s'il est pertinent pour la question, l'ignorer sinon]\n" +
        hits.map(h => `- ${h.title}: ${h.snippet}`).join("\n");
    }
  } catch (e) { /* pas de recherche -- le modèle répond sur ses connaissances */ }
  const messages = history.concat([{ role: "user", content: freeText + groundingBlock }]);
  let reply = "";
  try {
    reply = await anthropicComplete.call(this, ANTHROPIC_MODEL_EXPERT, buildExpertSystemPrompt(), messages, { maxTokens: 900, effort: "high" });
  } catch (e) { reply = ""; }
  if (!reply || !reply.trim()) {
    // On NE touche PAS à l'historique en cas d'échec -- l'équipe peut simplement retenter la même
    // question sans avoir perdu le fil de la conversation.
    result.text = "⚠️ Je n'ai pas pu réfléchir à ta question à l'instant (Anthropic indisponible ou clé non configurée). Réessaie dans un instant.";
  } else {
    const newHistory = history.concat([{ role: "user", content: freeText }, { role: "assistant", content: reply.trim() }]).slice(-CHAT_HISTORY_MAX_MESSAGES);
    staticData.sessions[sender] = Object.assign({}, state, { chat_history: newHistory });
    result.text = reply.trim();
  }
}

else if (command === "vision") {
  // FEEDBACK CRÉATIF SUR IMAGE (nouvelle fonctionnalité) : l'équipe envoie directement un visuel
  // (création Nuklear, brief client, pub concurrente...) et reçoit un avis d'expert digital, exactement
  // comme si elle montrait le visuel à un directeur artistique senior. Utilise le modèle le plus
  // capable (Opus) -- juger un design demande le même niveau de raisonnement que la conversation
  // experte, pas la génération de contenu à la chaîne.
  const media = await fetchWhatsAppImageBase64.call(this, imageId);
  if (!media) {
    result.text = "⚠️ Je n'ai pas pu récupérer cette image (jeton WhatsApp non configuré côté serveur, ou média expiré côté Meta). Réessaie avec une nouvelle image.";
  } else {
    const prompt = freeText && freeText.trim()
      ? `Voici un visuel envoyé par l'équipe Nuklear, avec cette question précise : "${freeText.trim()}". Réponds d'abord à la question, puis donne ton avis d'expert sur le visuel.`
      : "Voici un visuel envoyé par l'équipe Nuklear (création propre, brief client, ou pub concurrente -- le contexte exact n'est pas précisé). Donne un avis d'expert structuré : ce qui fonctionne, ce qui ne fonctionne pas, et 2-3 recommandations concrètes et actionnables pour l'améliorer -- design, lisibilité, hiérarchie visuelle, message, conformité à une charte de marque si elle est identifiable sur le visuel.";
    const messages = [{
      role: "user",
      content: [
        { type: "image", source: { type: "base64", media_type: media.mediaType, data: media.base64 } },
        { type: "text", text: prompt },
      ],
    }];
    let reply = "";
    try {
      reply = await anthropicComplete.call(this, ANTHROPIC_MODEL_EXPERT, buildExpertSystemPrompt(), messages, { maxTokens: 900, effort: "high" });
    } catch (e) { reply = ""; }
    result.text = (reply && reply.trim()) ? reply.trim() : "⚠️ Je n'ai pas pu analyser cette image à l'instant (Anthropic indisponible ou clé non configurée). Réessaie dans un instant.";
  }
}

else if (command === "gen_video") {
  const idea = await synthesizeIdea.call(this, "reels", freeText, null);
  const concept = "astuce_rapide";
  const beats = [
    `0-2s: accroche directe sur ${idea.hook}, cadrage serré`,
    "2-6s: démonstration de l'astuce en 2-3 étapes visuelles claires",
    "6-8s: résultat + punchline, logo Nuklear en overlay léger",
  ];
  let genPrompt = `Format: vidéo courte verticale 9:16, 8s max, style ${idea.tone}.\nConcept: ${concept}.\nAccroche: ${idea.hook}\nDécoupage:\n${beats.map(b => "- " + b).join("\n")}\nContraintes: texte ajouté en post-prod (police Inter) ; logo Nuklear en incrustation légère dernière seconde ; rythme dynamique.`;
  try {
    const refined = await anthropicComplete.call(this, ANTHROPIC_MODEL_FAST,
      `Tu es directeur créatif vidéo short-form pour Nuklear. Réécris UN prompt de génération vidéo précis à partir du concept/découpage fournis, style ${idea.tone}, français parfait. Réponds uniquement par le prompt, sans préambule ni guillemets.`,
      [{ role: "user", content: `Concept: ${concept}\nAccroche: ${idea.hook}\nDécoupage:\n${beats.map(b => "- " + b).join("\n")}` }],
      { maxTokens: 400, effort: "medium" });
    if (refined && refined.trim()) genPrompt = refined.trim();
  } catch (e) { /* on garde le prompt template */ }
  result.text = `🎬 *Prompt vidéo virale* (concept: ${concept})\n\nAccroche: ${idea.hook}\n\nDécoupage:\n${beats.map(b => "  " + b).join("\n")}\n\n*Prompt de génération:*\n${genPrompt}`;
}

else if (command === "gen_recrutement") {
  // Commande UTILITAIRE : champs saisis PRÉCISÉMENT par l'équipe, AUCUNE invention par le LLM (email/
  // contrat/lieu doivent être exacts). Rendu DIRECT (pas de propose-puis-"ok", contrairement à
  // gen_image) : il n'y a pas d'"idée" à valider, juste des champs à mettre en forme.
  const parts = freeText.split("|").map(s => s.trim()).filter(Boolean);
  const poste = parts[0];
  if (!poste) {
    result.text = "Format attendu : *gen recrutement: <poste> | <contrat> | <lieu> | <email>*\nEx: gen recrutement: Développeur Full Stack Senior | CDI | Antananarivo | recrutement@nuklear.io";
  } else {
    const fields = {
      poste,
      contrat: parts[1] || "CDI",
      lieu: parts[2] || "Antananarivo",
      email: parts[3] || "recrutement@nuklear.io",
    };
    const bgId = await resolveBrandBackground.call(this);
    const r = await tryTiers.call(this, buildRecruitmentTiers(fields, bgId));
    if (!r.tier) {
      result.text = `⚠️ Le montage du visuel recrutement a échoué. Réessaie dans un instant.\n\n_(diag: ${r.errors[r.errors.length - 1] || "inconnu"})_`;
    } else {
      result.image_url = r.tier.url;
      result.text = `✅ *Offre d'emploi prête à publier !*\n\n📌 ${fields.poste}\n📍 ${fields.contrat}, ${fields.lieu}\n✉️ ${fields.email}`;
    }
  }
}

else if (command === "gen_image" || command === "refresh" || command === "refine" ||
         command === "gen_collection" || command === "gen_avant_apres" || command === "gen_annonce") {
  // "refine" AJUSTE l'idée déjà proposée (previousIdea transmis) ; "refresh" en propose une
  // TOTALEMENT NOUVELLE (previousIdea = null) -- ne pas confondre les deux, comme côté Python
  // (orchestrator.py::_handle_refresh vs _handle_refine, testé explicitement).
  const previousIdea = (command === "refine") ? state.current_idea : null;
  const freeTextCommands = ["refine", "gen_image", "gen_collection", "gen_avant_apres", "gen_annonce"];
  const hint = freeTextCommands.includes(command) ? freeText : null;
  const forcedCategoryMap = { gen_collection: "collection", gen_avant_apres: "avant_apres", gen_annonce: "annonce" };
  const forcedCategory = forcedCategoryMap[command] || null;
  const idea = await synthesizeIdea.call(this, platform, hint, previousIdea, forcedCategory);
  // Filet de sécurité : force la catégorie même si le LLM ne l'a pas suivie à la lettre (fiabilité
  // garantie, indépendante de la détection automatique -- voir Extract & Route).
  if (forcedCategory) idea.category = forcedCategory;
  staticData.sessions[sender] = { stage: "idea_proposed", platform, current_idea: idea, refine_notes: state.refine_notes || [], chat_history: state.chat_history || [] };
  const prefix = command === "refresh" ? "🔄 Nouvelle proposition:\n\n" : (command === "refine" ? "✏️ Idée adaptée:\n\n" : "");
  result.text = prefix + formatIdea(idea, platform);
}

else if (command === "validate") {
  const idea = state.current_idea;
  if (!idea) {
    // Garde-fou défensif : état incohérent (ne devrait pas arriver, Extract & Route l'exige) --
    // on ne crashe jamais l'exécution (ce qui laisserait WhatsApp sans réponse).
    staticData.sessions[sender] = { stage: "idle", platform: null, current_idea: null, refine_notes: [], chat_history: state.chat_history || [] };
    result.text = "Rien à valider. Lance d'abord *gen image insta*.";
    return [{ json: result }];
  }
  let chosen = null, lastError = "", uploadDiag = "";

  const presetConfigured = CLOUDINARY_UPLOAD_PRESET && CLOUDINARY_UPLOAD_PRESET.indexOf("REPLACE_WITH") === -1;
  const pexelsConfigured = PEXELS_KEY && PEXELS_KEY.indexOf("REPLACE_WITH") === -1;
  // FOND DÉGRADÉ de marque : résolu UNE fois (upload initial puis cache, rotation déterministe --
  // voir nextInRotation) ; null = canevas noir uni.
  const bgId = await resolveBrandBackground.call(this);

  // ÉTAPE 0 -- GABARIT VIERGE fourni par l'utilisateur (fidélité charte maximale), si configuré.
  { const r = await tryTiers.call(this, buildTemplateTiers(idea.hook)); chosen = r.tier; if (r.errors.length) lastError = r.errors[r.errors.length - 1]; }

  // ÉTAPE 0.5 -- ANNONCE (format PAYSAGE, texte structuré) : purement textuel, comme le gabarit
  // ci-dessus -- pas de Pexels, pas d'IA, rendu 100% fiable. Fond dédié (pool paysage, distinct du
  // pool portrait) résolu séparément puisque les deux formats ne partagent pas les mêmes assets.
  if (!chosen && idea.category === "annonce") {
    const bgIdLandscape = await resolveLandscapeBackground.call(this);
    const r = await tryTiers.call(this, buildAnnonceTiers(idea, bgIdLandscape));
    chosen = r.tier; if (r.errors.length) lastError = r.errors[r.errors.length - 1];
  }

  // ÉTAPE 1 -- PHOTO(S) RÉELLE(S) de banque (Pexels, ZÉRO IA -> aucun faux texte possible) qui
  // ILLUSTRE(NT) l'idée. Nécessite une clé Pexels + un upload preset. Deux chemins selon la catégorie
  // auto-détectée : "avant_apres" cherche/uploade DEUX photos distinctes (split-screen) ; toute autre
  // catégorie (astuce, collection en repli) utilise une seule photo (mise en page 3 bandes). Repli
  // propre sur le poster de marque si indisponible dans tous les cas.
  if (!chosen && pexelsConfigured && presetConfigured && idea.category === "avant_apres") {
    // Recherche/upload SÉQUENTIELS (simple et fiable -- pas de concurrence à vérifier sans accès à
    // l'environnement Cloudinary réel).
    try {
      const beforeSubject = idea.visual_subject_before || `before state, problem: ${idea.visual_subject || idea.hook}`;
      const afterSubject = idea.visual_subject_after || `after state, success: ${idea.visual_subject || idea.hook}`;
      const beforeUrl = await pexelsSearchPhoto.call(this, beforeSubject);
      const afterUrl = beforeUrl ? await pexelsSearchPhoto.call(this, afterSubject) : null;
      if (beforeUrl && afterUrl) {
        const beforePid = await cloudinaryUploadFromUrl.call(this, beforeUrl);
        const afterPid = beforePid ? await cloudinaryUploadFromUrl.call(this, afterUrl) : null;
        if (beforePid && afterPid) {
          uploadDiag = "avant/après ok";
          const r = await tryTiers.call(this, buildBeforeAfterTiers(beforePid, afterPid, idea, bgId));
          chosen = r.tier; if (r.errors.length) lastError = r.errors[r.errors.length - 1];
        } else uploadDiag = "upload avant/après incomplet";
      } else uploadDiag = "photo(s) avant/après introuvable(s)";
    } catch (e) { uploadDiag = extractHttpError(e); }
  }

  if (!chosen && pexelsConfigured && presetConfigured && idea.category === "collection") {
    // COLLECTION : plusieurs photos distinctes (jusqu'à 4), recherchées/uploadées séquentiellement.
    // deriveCollectionSubjects() garantit toujours 4 sujets cohérents, même si le LLM a classé l'idée
    // en "collection" sans remplir visual_subjects -- avant ce garde-fou, ce cas retombait
    // SILENCIEUSEMENT sur le template "astuce" à une seule photo (voir commentaire de la fonction).
    // En dessous de 2 photos réellement obtenues (échec Pexels/Cloudinary), on abandonne la grille et
    // on retombe sur le chemin "photo unique" ci-après (mieux vaut UNE photo nette qu'une grille vide).
    try {
      const subjects = deriveCollectionSubjects(idea);
      const pids = [];
      for (const subj of subjects) {
        const url = await pexelsSearchPhoto.call(this, subj);
        if (url) { const pid = await cloudinaryUploadFromUrl.call(this, url); if (pid) pids.push(pid); }
      }
      if (pids.length >= 2) {
        uploadDiag = `collection ok (${pids.length}/${subjects.length})`;
        const r = await tryTiers.call(this, buildCollectionTiers(pids, idea, bgId));
        chosen = r.tier; if (r.errors.length) lastError = r.errors[r.errors.length - 1];
      } else uploadDiag = `collection insuffisante (${pids.length} photo(s))`;
    } catch (e) { uploadDiag = extractHttpError(e); }
  }

  if (!chosen && pexelsConfigured && presetConfigured) {
    try {
      const photoUrl = await pexelsSearchPhoto.call(this, idea.visual_subject || idea.hook);
      if (photoUrl) {
        const photoPid = await cloudinaryUploadFromUrl.call(this, photoUrl);
        if (photoPid) { uploadDiag = "photo ok"; const r = await tryTiers.call(this, buildPhotoEditorialTiers(photoPid, idea, bgId)); chosen = r.tier; if (r.errors.length) lastError = r.errors[r.errors.length - 1]; }
        else uploadDiag = "upload photo sans public_id";
      } else uploadDiag = "aucune photo Pexels trouvée";
    } catch (e) { uploadDiag = extractHttpError(e); }
  }

  // ÉTAPE 2 -- POSTER DE MARQUE DÉTERMINISTE (repli terminal, toujours tenté en dernier recours).
  // Canevas sombre + logo (haut-gauche) + kicker + H1 blanc + slogan bas-centre, uniquement à partir
  // d'ASSETS STOCKÉS. Aucune IA générative, aucun texte parasite possible, aucune dépendance fragile
  // (ni "Fetched URL" ni upload externe). Rendu IDENTIQUE et prêt à publier À CHAQUE FOIS -> zéro
  // génération gaspillée en résultat inpubliable. (L'ancien repli "illustration IA" Pollinations a été
  // supprimé : il incrustait des faux textes/objets dans l'image de façon incontrôlable -- inutilisable
  // en prod, voir historique de commits.)
  if (!chosen) { const r = await tryTiers.call(this, buildBrandCanvasTiers(idea.hook, idea.kicker, bgId)); chosen = r.tier; if (r.errors.length) lastError = r.errors[r.errors.length - 1]; }

  if (!chosen) {
    staticData.sessions[sender] = { stage: "idle", platform: null, current_idea: null, refine_notes: [], chat_history: state.chat_history || [] };
    result.text = `⚠️ Le montage du visuel a échoué (Cloudinary indisponible, ou LOGO_PUBLIC_ID non configuré). Réessaie dans un instant.\n\n_(diag: ${lastError})_`;
    return [{ json: result }];
  }

  staticData.sessions[sender] = { stage: "idle", platform: null, current_idea: null, refine_notes: [], chat_history: state.chat_history || [] };
  result.image_url = chosen.url;
  const diagTail = uploadDiag ? `upload=${uploadDiag} ; ${lastError}` : lastError;
  // LÉGENDE PRÊTE À PUBLIER envoyée AVEC l'image : caption on-brand + hashtags populaires, pour que
  // l'équipe n'ait qu'à copier-coller lors de la publication (demande utilisateur).
  const caption = String(idea.caption || idea.hook || "");
  const tags = (idea.hashtags && idea.hashtags.length) ? idea.hashtags.join(" ") : "";
  const post = `${caption}${tags ? "\n\n" + tags : ""}`;
  // Rendu "complet" = gabarit auto, photo éditoriale, collection, avant-après, annonce, ou gabarit
  // fourni + texte. Reconnaît TOUS les labels de rendu "complet" (chaque builder a ses propres
  // libellés) -- avant ce correctif, les nouveaux templates (collection/avant-après/annonce)
  // n'étaient reconnus par AUCUN de ces mots-clés et s'affichaient donc TOUJOURS comme "montage
  // partiel", même en cas de succès.
  const isFull = ["gabarit auto", "photo", "+ texte", "collection", "avant-après", "annonce"].some(s => chosen.label && chosen.label.indexOf(s) !== -1);
  if (!isFull) {
    result.text = `✅ *Visuel prêt* (montage partiel : ${chosen.label}) :\n\n${post}\n\n_(diag: ${diagTail})_`;
  } else {
    result.text = `✅ *Prêt à publier !*\n\n${post}`;
  }
}

return [{ json: result }];
